import 'dart:convert';
import 'package:http/http.dart' as http;
import '../../core/config/api_settings.dart';
import '../models/sms_model.dart';
class SmsApiRepository { final String _initialBaseUrl; String get baseUrl=>ApiSettings.current.baseUrl.isNotEmpty?ApiSettings.current.baseUrl:_initialBaseUrl; SmsApiRepository({required String baseUrl}):_initialBaseUrl=baseUrl; Future<SendSmsResponse> sendSms(String mobile,String message,{int? personId})async{final r=await http.post(Uri.parse('$baseUrl/api/sms/send'),headers:{'Content-Type':'application/json'},body:jsonEncode({'mobile':mobile,'message':message,'personId':personId}));if(r.statusCode==200)return SendSmsResponse.fromJson(jsonDecode(r.body));throw Exception('خطا در ارسال پیامک');} Future<List<SmsLogModel>> getLogs({int? personId})async{final uri=Uri.parse('$baseUrl/api/sms/logs').replace(queryParameters:personId!=null?{'personId':personId.toString()}:null);final r=await http.get(uri);if(r.statusCode==200)return(jsonDecode(r.body)as List<dynamic>).map((e)=>SmsLogModel.fromJson(e)).toList();throw Exception('خطا در دریافت لاگ‌های پیامک');} }
